import static com.xenris.liquidwarsos.World170ProbeTest.*;
import android.content.*;import android.graphics.*;import android.os.*;import android.view.*;import android.widget.*;
import androidx.test.core.app.ActivityScenario;import androidx.test.ext.junit.runners.AndroidJUnit4;import androidx.lifecycle.Lifecycle;
